#pragma once

#include <common/ChunkTrackerEntry.hh>
#include <map>

namespace AstraSimAnalytical {

/**
 * ChunkTracker keeps track of the ChunkTrackerEntry's for a given request. Used
 * to track the state (ChunkReqType) and original request (sim_request) of a
 * chunk in the network.
 */
class ChunkTracker {
  public:
    ChunkTracker() noexcept;

    /**
     * Search for the entry identified by request ID generated by the network
     * frontend tuple.
     *
     * @param req_id the unique identifier for this chunk
     * @return the found entry if exists, std::nullopt otherwise
     */
    std::optional<ChunkTrackerEntry*> search_entry(
        const RequestID req_id) const noexcept;

    /**
     * Find the entry identified by req_id, or create one if it doesn't exist
     * yet. A Send and its matching Recv share the same req_id (see ReqId.hh),
     * so whichever of the two calls second finds the entry the first one
     * created instead of allocating a new one.
     *
     * @param req_id the RequestID unique identifier for this chunk
     * @param chunk_type the AstraNetworkAPI::CommandType to decide what
     * (derived) type of entry object to create, if one doesn't exist yet
     *
     * @return the found or newly created entry
     */
    ChunkTrackerEntry* create_new_entry(
        const AstraNetworkAPI::CommandType chunk_type,
        const sim_request& request) noexcept;

    /**
     * Remove the entry identified by request ID generated by the network
     * frontend
     *
     * @param req_id the unique identifier for this chunk
     */
    void pop_entry(const RequestID req_id) noexcept;

  private:
    /// map from RequestID to ChunkTrackerEntry
    std::unordered_map<RequestID, ChunkTrackerEntry*> tracker;
};

}  // namespace AstraSimAnalytical
